/// The frame as bytes; a frame that cannot be written is none.
fn bytes<F: Encode>(frame: &F) -> Option<Vec<u8>> {
    let mut out = Vec::new();
    frame.encode(&mut Writer::new(&mut out)).ok()?;
    Some(out)
}
